class MRope:
    def __init__(self):
        pass
        self.fwd_kernel = _m().m_rope
        self.inplace_kernel = _m().m_rope_inplace
        self.pack_kernel = _m().m_rope_inplace_pack
        self.pack_bwd_kernel = _m().m_rope_inplace_pack_bwd
        self.cfg_cache_write_kernel = _m().m_rope_inplace_cfg_cache_write
        self.bwd_kernel = _m().m_rope_bwd

    def pack(
        self,
        qkv,
        q_num_heads,
        kv_num_heads,
        cos,
        sin,
        mrope_section,
        inference=False,
    ):
        """原地对packed qkv的q/k部分应用mrope，并返回同一个qkv张量。支持GQA。

        Split/view/offset calculations are done on the C++ side. qkv must be 3D: [bz, seq_len, q_dim+2*kv_dim].

        Args:
            qkv:          [bz, seq_len, q_dim + 2*kv_dim]
            q_num_heads:  number of query heads
            kv_num_heads: number of key/value heads
            cos, sin:     rotary position encoding [3, bz, seq_len, head_dim/2]
            mrope_section: (first, second) M-RoPE section parameters
            inference:     只执行前向原地kernel，不接入autograd
        """
        if inference:
            self.pack_kernel(
                qkv,
                cos,
                sin,
                q_num_heads,
                kv_num_heads,
                mrope_section[0],
                mrope_section[1],
            )
            return qkv

        return _MRopePackFunction.apply(
            qkv,
            q_num_heads,
            kv_num_heads,
            cos,
            sin,
            mrope_section,
            self.pack_kernel,
            self.pack_bwd_kernel,
        )

    def pack_backward(self, dqkv, q_num_heads, kv_num_heads, cos, sin, mrope_section):
        """原地对packed dqkv的dq/dk部分应用mrope backward，并返回dqkv。"""
        self.pack_bwd_kernel(
            dqkv,
            cos,
            sin,
            q_num_heads,
            kv_num_heads,
            mrope_section[0],
            mrope_section[1],
        )
        return dqkv

    def cfg_cache_write(
        self,
        q,
        k,
        v,
        cos,
        sin,
        mrope_section,
        kvcache,
        valid0,
        valid1,
        common_len,
        cond_tail_len,
    ):
        """In-place mrope(q, k) fused with CFG packed prefill KV-cache write.

        This is inference-only. `q`, `k`, and `v` are packed single-batch
        tensors [1, packed_seq, heads, head_dim]. `kvcache` is the per-layer
        static cache view [2, max_batch, max_len, kv_heads, head_dim].
        """
        self.cfg_cache_write_kernel(
            q,
            k,
            v,
            cos,
            sin,
            kvcache,
            valid0,
            valid1,
            int(common_len),
            int(cond_tail_len),
            mrope_section[0],
            mrope_section[1],
        )
        return q, k

    def __call__(self, q, k, cos, sin, mrope_section, inference=False):
        if inference:
            first = mrope_section[0]
            second = mrope_section[1]
            self.inplace_kernel(q, k, cos, sin, first, second)
            return q, k

        return _MRopeFunction.apply(
            q,
            k,
            cos,
            sin,
            mrope_section,
            self.fwd_kernel,
            self.bwd_kernel,
        )




class RotPos:
    def __init__(self):
        pass

    def __call__(
        self, inv_freq, grid_thw, spatial_merge_size, total_output_tokens=None
    ):
        assert (
            inv_freq.dtype == torch.float32
        ), f"Expected float32, got {inv_freq.dtype}"
        get_token_counts_kernel = _m().get_token_counts
        rot_pos_kernel = _m().rot_pos

        num_grids = grid_thw.size(0)
        token_counts = torch.zeros(
            (num_grids), dtype=grid_thw.dtype, device=grid_thw.device
        )

        get_token_counts_kernel(grid_thw, token_counts, spatial_merge_size)
        cumsum_tokens = torch.cat(
            [
                torch.zeros(1, dtype=token_counts.dtype, device=token_counts.device),
                token_counts.cumsum(dim=0),
            ],
            dim=0,
        ).to(grid_thw.dtype)

        if total_output_tokens is None:
            total_output_tokens = cumsum_tokens[-1].item()

        output = torch.empty(
            (total_output_tokens, inv_freq.size(0) * 2),
            dtype=torch.float,
            device=inv_freq.device,
        )
        rot_pos_kernel(inv_freq, grid_thw, output, cumsum_tokens, spatial_merge_size)

        return output




