get_window_index_kernel = _m().get_window_index
get_totals_kernel = _m().get_totals


def get_window_index_cuda(
    grid_thw, window_size, spatial_merge_size, patch_size, spatial_merge_unit=1
):

    if grid_thw.size(0) == 0:
        return (
            torch.empty(0, dtype=grid_thw.dtype, device=grid_thw.device),
            torch.zeros(1, dtype=grid_thw.dtype, device=grid_thw.device),
        )

    vit_merger_window_size = window_size // spatial_merge_size // patch_size

    grid_info_tensor = torch.empty(
        (grid_thw.size(0), 6), dtype=grid_thw.dtype, device=grid_thw.device
    )
    global_totals_tensor = torch.zeros(
        (2), dtype=grid_thw.dtype, device=grid_thw.device
    )
    get_totals_kernel(
        grid_thw,
        grid_info_tensor,
        global_totals_tensor,
        spatial_merge_size,
        vit_merger_window_size,
    )
    total_elements = global_totals_tensor[0].item()
    total_windows = global_totals_tensor[1].item()
    if total_elements == 0 or total_windows == 0:
        return (
            torch.empty(0, dtype=grid_thw.dtype, device=grid_thw.device),
            torch.zeros(1, dtype=grid_thw.dtype, device=grid_thw.device),
        )

    window_indices = torch.empty(
        total_elements, dtype=grid_thw.dtype, device=grid_thw.device
    )
    cu_window_seqlens = torch.empty(
        (total_windows + 1), dtype=grid_thw.dtype, device=grid_thw.device
    )
    window_counts_tensor = torch.empty(
        (total_windows), dtype=grid_thw.dtype, device=grid_thw.device
    )

    max_grid_t = grid_thw[:, 0].max().item()
    get_window_index_kernel(
        grid_thw,
        grid_info_tensor,
        window_indices,
        cu_window_seqlens,
        window_counts_tensor,
        max_grid_t,
        spatial_merge_size,
        vit_merger_window_size,
        patch_size,
        spatial_merge_unit,
    )

    return window_indices, cu_window_seqlens


"""Fused position embedding interpolation for Qwen3.5 ViT.

Single CUDA kernel: bilinear interpolation + spatial merge permutation.
Each output token independently computes its result — no intermediate tensors,
no Python loops, no GPU-CPU synchronization.
"""



def _reference_pos_embed_interp(
    grid_thw: torch.Tensor,
    pos_embed_weight: torch.Tensor,
    num_grid_per_side: int,
    spatial_merge_size: int,
) -> torch.Tensor:
    grid_thw_list = grid_thw.tolist()
    grid_ts = [row[0] for row in grid_thw_list]
    grid_hs = [row[1] for row in grid_thw_list]
    grid_ws = [row[2] for row in grid_thw_list]
    device = pos_embed_weight.device

    idx_list = [[] for _ in range(4)]
    weight_list = [[] for _ in range(4)]

    for _t, h, w in grid_thw_list:
        h_idxs = torch.linspace(0, num_grid_per_side - 1, h)
        w_idxs = torch.linspace(0, num_grid_per_side - 1, w)

        h_idxs_floor = h_idxs.int()
        w_idxs_floor = w_idxs.int()
        h_idxs_ceil = (h_idxs.int() + 1).clip(max=num_grid_per_side - 1)
        w_idxs_ceil = (w_idxs.int() + 1).clip(max=num_grid_per_side - 1)

        dh = h_idxs - h_idxs_floor
        dw = w_idxs - w_idxs_floor

        base_h = h_idxs_floor * num_grid_per_side
        base_h_ceil = h_idxs_ceil * num_grid_per_side

        indices = [
            (base_h[None].T + w_idxs_floor[None]).flatten(),
            (base_h[None].T + w_idxs_ceil[None]).flatten(),
            (base_h_ceil[None].T + w_idxs_floor[None]).flatten(),
            (base_h_ceil[None].T + w_idxs_ceil[None]).flatten(),
        ]
        weights = [
            ((1 - dh)[None].T * (1 - dw)[None]).flatten(),
            ((1 - dh)[None].T * dw[None]).flatten(),
            (dh[None].T * (1 - dw)[None]).flatten(),
            (dh[None].T * dw[None]).flatten(),
        ]
        for i in range(4):
            idx_list[i].extend(indices[i].tolist())
            weight_list[i].extend(weights[i].tolist())

    idx_tensor = torch.tensor(idx_list, dtype=torch.long, device=device)
    weight_tensor = torch.tensor(
        weight_list, dtype=pos_embed_weight.dtype, device=device
    )
    pos_embeds = pos_embed_weight[idx_tensor] * weight_tensor[:, :, None]
    patch_pos_embeds = pos_embeds[0] + pos_embeds[1] + pos_embeds[2] + pos_embeds[3]

    patch_pos_embeds = patch_pos_embeds.split([h * w for h, w in zip(grid_hs, grid_ws)])

    patch_pos_embeds_permute = []
    merge_size = spatial_merge_size
    for pos_embed, t, h, w in zip(patch_pos_embeds, grid_ts, grid_hs, grid_ws):
        pos_embed = pos_embed.repeat(t, 1)
        pos_embed = (
            pos_embed.view(
                t, h // merge_size, merge_size, w // merge_size, merge_size, -1
            )
            .permute(0, 1, 3, 2, 4, 5)
            .flatten(0, 4)
        )
        patch_pos_embeds_permute.append(pos_embed)
    return torch.cat(patch_pos_embeds_permute)


class _PosEmbedInterpFunction(torch.autograd.Function):
    @staticmethod
    def forward(
        ctx,
        op,
        grid_thw,
        pos_embed_weight,
        num_grid_per_side,
        spatial_merge_size,
        total_output_tokens,
    ):
        ctx.op = op
        ctx.num_grid_per_side = num_grid_per_side
        ctx.spatial_merge_size = spatial_merge_size
        (
            grid_thw,
            out_cumsum,
            hw_cumsum,
            total_output,
        ) = op._prepare_cuda_metadata(
            grid_thw, pos_embed_weight, total_output_tokens=total_output_tokens
        )
        ctx.save_for_backward(grid_thw, out_cumsum, hw_cumsum, pos_embed_weight)
        return op._forward_cuda_prepared(
            grid_thw,
            pos_embed_weight,
            out_cumsum,
            hw_cumsum,
            num_grid_per_side,
            spatial_merge_size,
            total_output,
        )

    @staticmethod
    def backward(ctx, grad_output):
        if not ctx.needs_input_grad[2]:
            return None, None, None, None, None, None

        grid_thw, out_cumsum, hw_cumsum, pos_embed_weight = ctx.saved_tensors
        grad_output = grad_output.contiguous().float()
        grad_weight = torch.zeros(
            pos_embed_weight.shape,
            dtype=torch.float32,
            device=pos_embed_weight.device,
        )
        ctx.op.backward_kernel(
            grad_output,
            grid_thw,
            out_cumsum,
            hw_cumsum,
            grad_weight,
            ctx.num_grid_per_side,
            ctx.spatial_merge_size,
        )
        if pos_embed_weight.dtype != torch.float32:
            grad_weight = grad_weight.to(pos_embed_weight.dtype)
        return None, None, grad_weight, None, None, None


class PosEmbedInterp:
    """Fused bilinear interpolation of position embeddings with spatial merge.

    Replaces ~20 PyTorch kernel launches with 1 fused CUDA kernel.
    """

    def __init__(self):
        pass
        self.kernel = _m().pos_embed_interp
        self.backward_kernel = _m().pos_embed_interp_backward

    def _prepare_cuda_metadata(
        self,
        grid_thw: torch.Tensor,
        pos_embed_weight: torch.Tensor,
        total_output_tokens: int | None = None,
    ) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor, int]:
        device = pos_embed_weight.device
        grid_thw = grid_thw.to(dtype=torch.int32, device=device).contiguous()

        ts = grid_thw[:, 0]
        hs = grid_thw[:, 1]
        ws = grid_thw[:, 2]

        hw_products = hs * ws
        thw_products = ts * hs * ws

        hw_cumsum = torch.zeros(grid_thw.shape[0] + 1, dtype=torch.int32, device=device)
        hw_cumsum[1:] = hw_products.cumsum(0)

        out_cumsum = torch.zeros(
            grid_thw.shape[0] + 1, dtype=torch.int32, device=device
        )
        out_cumsum[1:] = thw_products.cumsum(0)

        if total_output_tokens is not None:
            total_output = total_output_tokens
        else:
            # Fallback: requires GPU->CPU sync
            total_output = out_cumsum[-1].item()

        return grid_thw, out_cumsum, hw_cumsum, total_output

    def _forward_cuda_prepared(
        self,
        grid_thw: torch.Tensor,
        pos_embed_weight: torch.Tensor,
        out_cumsum: torch.Tensor,
        hw_cumsum: torch.Tensor,
        num_grid_per_side: int,
        spatial_merge_size: int,
        total_output: int,
    ) -> torch.Tensor:
        weight = pos_embed_weight.contiguous()
        hidden_dim = weight.shape[1]
        output = torch.empty(
            total_output,
            hidden_dim,
            dtype=weight.dtype,
            device=pos_embed_weight.device,
        )

        self.kernel(
            weight,
            grid_thw.contiguous(),
            out_cumsum,
            hw_cumsum,
            output,
            num_grid_per_side,
            spatial_merge_size,
        )

        return output

    def _forward_cuda(
        self,
        grid_thw: torch.Tensor,
        pos_embed_weight: torch.Tensor,
        num_grid_per_side: int,
        spatial_merge_size: int,
        total_output_tokens: int | None = None,
    ) -> torch.Tensor:
        """
        Args:
            grid_thw: (num_images, 3) int32 tensor of (t, h, w) per image.
            pos_embed_weight: (N*N, hidden_dim) embedding weight.
            num_grid_per_side: N (sqrt of num_position_embeddings).
            spatial_merge_size: merge size for spatial dims.
            total_output_tokens: pre-computed total output token count (Python int).
                If provided, avoids a GPU->CPU sync inside this function.

        Returns:
            (total_output_tokens, hidden_dim) tensor.
        """
        (
            grid_thw,
            out_cumsum,
            hw_cumsum,
            total_output,
        ) = self._prepare_cuda_metadata(
            grid_thw, pos_embed_weight, total_output_tokens=total_output_tokens
        )
        return self._forward_cuda_prepared(
            grid_thw,
            pos_embed_weight,
            out_cumsum,
            hw_cumsum,
            num_grid_per_side,
            spatial_merge_size,
            total_output,
        )

    def __call__(
        self,
        grid_thw: torch.Tensor,
        pos_embed_weight: torch.Tensor,
        num_grid_per_side: int,
        spatial_merge_size: int,
        total_output_tokens: int | None = None,
    ) -> torch.Tensor:
        if torch.is_grad_enabled() and pos_embed_weight.requires_grad:
            return _PosEmbedInterpFunction.apply(
                self,
                grid_thw,
                pos_embed_weight,
                num_grid_per_side,
                spatial_merge_size,
                total_output_tokens,
            )
        return self._forward_cuda(
            grid_thw,
            pos_embed_weight,
            num_grid_per_side,
            spatial_merge_size,
            total_output_tokens=total_output_tokens,
        )





class Qwen35GetRopeIndex:
    """Qwen3.5 mRoPE index kernel using mm_token_type_ids groups."""

    def __init__(self):
        pass

    def __call__(
        self,
        input_ids,
        mm_token_type_ids,
        image_grid_thw=None,
        video_grid_thw=None,
        attention_mask=None,
        spatial_merge_size=1,
    ):
        if input_ids is None:
            raise RuntimeError("qwen35_get_rope_index expects input_ids")
        if mm_token_type_ids is None:
            raise RuntimeError("qwen35_get_rope_index expects mm_token_type_ids")
        if input_ids.dim() != 2:
            raise RuntimeError("qwen35_get_rope_index expects input_ids shape [B, S]")
        if mm_token_type_ids.shape != input_ids.shape:
            raise RuntimeError(
                "qwen35_get_rope_index expects mm_token_type_ids shape [B, S]"
            )
        if not input_ids.is_cuda:
            raise RuntimeError("qwen35_get_rope_index expects CUDA tensors")

        input_ids = input_ids.contiguous()
        mm_token_type_ids = mm_token_type_ids.contiguous()
        if image_grid_thw is not None:
            image_grid_thw = image_grid_thw.contiguous()
        if video_grid_thw is not None:
            video_grid_thw = video_grid_thw.contiguous()
        if attention_mask is not None:
            attention_mask = attention_mask.contiguous()

        get_workspace = _m().qwen35_get_rope_index_getworkspace
        kernel = _m().qwen35_get_rope_index
        workspace_size = get_workspace(input_ids)
        workspace = torch.empty(
            workspace_size, dtype=torch.uint8, device=input_ids.device
        )
        batch_size, seq_len = input_ids.shape
        position_ids = torch.empty(
            (3, batch_size, seq_len), dtype=torch.int64, device=input_ids.device
        )
        mrope_deltas = torch.empty(
            (batch_size, 1), dtype=torch.int64, device=input_ids.device
        )

        kernel(
            input_ids,
            mm_token_type_ids,
            image_grid_thw,
            video_grid_thw,
            attention_mask,
            position_ids,
            mrope_deltas,
            workspace,
            spatial_merge_size,
        )
        return position_ids, mrope_deltas





def _require_cuda_2d(tensor: torch.Tensor, name: str):
    if not isinstance(tensor, torch.Tensor):
        raise RuntimeError(f"{name} must be a tensor")
    if not tensor.is_cuda:
        raise RuntimeError(f"{name} must be a CUDA tensor")
    if tensor.dim() != 2:
        raise RuntimeError(f"{name} expects shape [B, S]")


def _optional_mask(tensor, name, shape, device, dtype):
    if tensor is None:
        return None
    if not isinstance(tensor, torch.Tensor):
        raise RuntimeError(f"{name} must be a tensor or None")
    if tensor.shape != shape:
        raise RuntimeError(
            f"{name} expects shape {tuple(shape)}, got {tuple(tensor.shape)}"
        )
    if tensor.device != device:
        raise RuntimeError(f"{name} must be on the same device")
    if tensor.dtype != dtype:
        tensor = (tensor != 0) if dtype == torch.bool else tensor.to(dtype)
    return tensor.contiguous()


def _optional_bool_mask(tensor, name, shape, device):
    return _optional_mask(tensor, name, shape, device, torch.bool)


def _optional_i64_mask(tensor, name, shape, device):
    return _optional_mask(tensor, name, shape, device, torch.int64)


def _normalize_rope_gap(rtc_rope_gap):
    if isinstance(rtc_rope_gap, torch.Tensor):
        rtc_rope_gap = rtc_rope_gap.item()
    return int(rtc_rope_gap or 0)


def qwen35_update_joint_attention_flash_mask_kernel(
    moe_token_types,
    padding_positions=None,
    ar_predict_token_positions=None,
    valid_flow_action_positions=None,
    ar_action_mask=None,
    flow_block_id=None,
    rtc_pinned=None,
    causal_action_attention_mask=False,
    ar_visible=True,
    num_kv_heads=1,
):
    _require_cuda_2d(moe_token_types, "moe_token_types")
    shape = moe_token_types.shape
    device = moe_token_types.device
    if moe_token_types.dtype != torch.bool:
        moe_token_types = moe_token_types != 0
    moe_token_types = moe_token_types.contiguous()

    padding_positions = _optional_bool_mask(
        padding_positions, "padding_positions", shape, device
    )
    ar_predict_token_positions = _optional_bool_mask(
        ar_predict_token_positions, "ar_predict_token_positions", shape, device
    )
    valid_flow_action_positions = _optional_bool_mask(
        valid_flow_action_positions, "valid_flow_action_positions", shape, device
    )
    ar_action_mask = _optional_bool_mask(
        ar_action_mask, "ar_action_mask", shape, device
    )
    flow_block_id = _optional_i64_mask(flow_block_id, "flow_block_id", shape, device)
    rtc_pinned = _optional_bool_mask(rtc_pinned, "rtc_pinned", shape, device)

    batch_size, seq_len = shape
    num_kv_heads = int(num_kv_heads)
    if num_kv_heads < 1:
        raise RuntimeError(f"num_kv_heads must be >= 1, got {num_kv_heads}")
    output = torch.empty(
        (batch_size, num_kv_heads, seq_len, 2), dtype=torch.int32, device=device
    )
    _m().qwen35_update_joint_attention_flash_mask(
        output,
        moe_token_types,
        padding_positions,
        ar_predict_token_positions,
        valid_flow_action_positions,
        ar_action_mask,
        flow_block_id,
        rtc_pinned,
        bool(causal_action_attention_mask),
        bool(ar_visible),
        num_kv_heads,
    )
    return output


def qwen35_update_position_ids_kernel(
    position_ids,
    moe_token_types,
    ar_predict_token_positions=None,
    flow_block_id=None,
    rtc_pinned=None,
    rtc_rope_gap=0,
):
    if not isinstance(position_ids, torch.Tensor):
        raise RuntimeError("position_ids must be a tensor")
    if not position_ids.is_cuda:
        raise RuntimeError("position_ids must be a CUDA tensor")
    if position_ids.dim() != 3:
        raise RuntimeError("position_ids expects shape [D, B, S]")
    if position_ids.dtype != torch.int64:
        raise RuntimeError("position_ids must be int64")
    _require_cuda_2d(moe_token_types, "moe_token_types")
    if moe_token_types.shape != position_ids.shape[1:]:
        raise RuntimeError(
            "moe_token_types shape must match position_ids [B, S], "
            f"got {tuple(moe_token_types.shape)} vs {tuple(position_ids.shape[1:])}"
        )
    if moe_token_types.device != position_ids.device:
        raise RuntimeError("moe_token_types must be on the same device")

    shape = moe_token_types.shape
    device = moe_token_types.device
    if moe_token_types.dtype != torch.bool:
        moe_token_types = moe_token_types != 0
    moe_token_types = moe_token_types.contiguous()
    position_ids = position_ids.contiguous()
    ar_predict_token_positions = _optional_bool_mask(
        ar_predict_token_positions, "ar_predict_token_positions", shape, device
    )
    flow_block_id = _optional_i64_mask(flow_block_id, "flow_block_id", shape, device)
    rtc_pinned = _optional_bool_mask(rtc_pinned, "rtc_pinned", shape, device)

    output = torch.empty_like(position_ids)
    _m().qwen35_update_position_ids(
        output,
        position_ids,
        moe_token_types,
        ar_predict_token_positions,
        flow_block_id,
        rtc_pinned,
        _normalize_rope_gap(rtc_rope_gap),
    )
    return output





def _check_args(
    mixed_qkv: torch.Tensor,
    num_k_heads: int,
    num_v_heads: int,
    head_k_dim: int,
    head_v_dim: int,
):
    if not isinstance(mixed_qkv, torch.Tensor):
        raise RuntimeError("mixed_qkv must be a tensor")
    if mixed_qkv.is_cpu:
        raise RuntimeError("gated_delta_post_conv_pack expects a CUDA tensor")
    if mixed_qkv.dim() != 3:
        raise RuntimeError(
            "gated_delta_post_conv_pack expects mixed_qkv shape [B, C, T]"
        )

    num_k_heads = int(num_k_heads)
    num_v_heads = int(num_v_heads)
    head_k_dim = int(head_k_dim)
    head_v_dim = int(head_v_dim)
    if num_k_heads <= 0 or num_v_heads <= 0 or head_k_dim <= 0 or head_v_dim <= 0:
        raise RuntimeError("head counts and dims must be positive")
    if num_v_heads % num_k_heads != 0:
        raise RuntimeError("num_v_heads must be divisible by num_k_heads")

    expected_channels = 2 * num_k_heads * head_k_dim + num_v_heads * head_v_dim
    if mixed_qkv.size(1) != expected_channels:
        raise RuntimeError(
            f"mixed_qkv channel mismatch: got {mixed_qkv.size(1)}, "
            f"expected {expected_channels}"
        )
    return num_k_heads, num_v_heads, head_k_dim, head_v_dim


def _first_not_none(*tensors):
    for tensor in tensors:
        if tensor is not None:
            return tensor
    return None


def _zero_or_contiguous(
    grad: torch.Tensor | None,
    shape: tuple[int, ...],
    *,
    like: torch.Tensor,
) -> torch.Tensor:
    if grad is None:
        return torch.zeros(shape, dtype=like.dtype, device=like.device)
    if grad.shape != shape:
        raise RuntimeError(
            f"grad shape mismatch: got {tuple(grad.shape)}, expected {shape}"
        )
    if grad.dtype != like.dtype:
        raise RuntimeError("grad dtype mismatch")
    if grad.device != like.device:
        raise RuntimeError("grad device mismatch")
    if not grad.is_contiguous():
        grad = grad.contiguous()
    return grad


def _l2norm(x: torch.Tensor, eps: float = 1e-6) -> torch.Tensor:
    return (
        x.float()
        * torch.rsqrt(torch.sum(x.float() * x.float(), dim=-1, keepdim=True) + eps)
    ).to(x.dtype)


def _alloc_packed_qkv(
    batch_size: int,
    seq_length: int,
    num_v_heads: int,
    head_k_dim: int,
    head_v_dim: int,
    *,
    like: torch.Tensor,
) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor]:
    """Allocate q/k/v output buffers: one packed [3, ...] tensor when the head
    dims match (so q/k/v stay adjacent for the packed kernel path), separate
    tensors otherwise."""
    if head_k_dim == head_v_dim:
        packed_qkv = torch.empty(
            (3, batch_size, seq_length, num_v_heads, head_k_dim),
            dtype=like.dtype,
            device=like.device,
        )
        return packed_qkv.unbind(0)
    query = torch.empty(
        (batch_size, seq_length, num_v_heads, head_k_dim),
        dtype=like.dtype,
        device=like.device,
    )
    key = torch.empty_like(query)
    value = torch.empty(
        (batch_size, seq_length, num_v_heads, head_v_dim),
        dtype=like.dtype,
        device=like.device,
    )
    return query, key, value


def _check_gate_args(
    mixed_qkv: torch.Tensor,
    b: torch.Tensor,
    a: torch.Tensor,
    A_log: torch.Tensor,
    dt_bias: torch.Tensor,
    num_v_heads: int,
):
    batch_size, _, seq_length = mixed_qkv.shape
    gate_shape = (batch_size, seq_length, num_v_heads)
    if b.shape != gate_shape:
        raise RuntimeError(
            f"b shape mismatch: got {tuple(b.shape)}, expected {gate_shape}"
        )
    if a.shape != gate_shape:
        raise RuntimeError(
            f"a shape mismatch: got {tuple(a.shape)}, expected {gate_shape}"
        )
    if A_log.shape != (num_v_heads,):
        raise RuntimeError(
            f"A_log shape mismatch: got {tuple(A_log.shape)}, expected {(num_v_heads,)}"
        )
    if dt_bias.shape != (num_v_heads,):
        raise RuntimeError(
            f"dt_bias shape mismatch: got {tuple(dt_bias.shape)}, expected {(num_v_heads,)}"
        )
    for name, tensor in (("b", b), ("a", a), ("A_log", A_log), ("dt_bias", dt_bias)):
        if tensor.device != mixed_qkv.device:
            raise RuntimeError(f"{name} device mismatch")
    if b.dtype != mixed_qkv.dtype or a.dtype != mixed_qkv.dtype:
        raise RuntimeError("b/a dtype must match mixed_qkv dtype")


def _can_use_preprocess_fast_path(
    mixed_qkv: torch.Tensor,
    b: torch.Tensor,
    a: torch.Tensor,
    A_log: torch.Tensor,
    dt_bias: torch.Tensor,
    num_k_heads: int,
    num_v_heads: int,
    head_k_dim: int,
    head_v_dim: int,
) -> bool:
    if num_k_heads != 16 or num_v_heads != 32 or head_k_dim != 128 or head_v_dim != 128:
        return False
    if not mixed_qkv.is_cuda or mixed_qkv.dim() != 3:
        return False
    if mixed_qkv.stride(1) != 1:
        return False
    if b.stride(-1) != 1 or a.stride(-1) != 1:
        return False
    if not A_log.is_contiguous() or not dt_bias.is_contiguous():
        return False
    if A_log.dtype != torch.float32 or dt_bias.dtype != torch.float32:
        return False
    return True


class _GatedDeltaPostConvPack(torch.autograd.Function):
    @staticmethod
    def forward(
        ctx,
        mixed_qkv: torch.Tensor,
        num_k_heads: int,
        num_v_heads: int,
        head_k_dim: int,
        head_v_dim: int,
    ):
        num_k_heads, num_v_heads, head_k_dim, head_v_dim = _check_args(
            mixed_qkv,
            num_k_heads,
            num_v_heads,
            head_k_dim,
            head_v_dim,
        )

        batch_size, _, seq_length = mixed_qkv.shape
        query, key, value = _alloc_packed_qkv(
            batch_size,
            seq_length,
            num_v_heads,
            head_k_dim,
            head_v_dim,
            like=mixed_qkv,
        )
        _m().gated_delta_post_conv_pack(
            query,
            key,
            value,
            mixed_qkv,
            num_k_heads,
            num_v_heads,
            head_k_dim,
            head_v_dim,
        )

        ctx.input_shape = tuple(mixed_qkv.shape)
        ctx.input_stride = tuple(mixed_qkv.stride())
        ctx.num_k_heads = num_k_heads
        ctx.num_v_heads = num_v_heads
        ctx.head_k_dim = head_k_dim
        ctx.head_v_dim = head_v_dim
        return query, key, value

    @staticmethod
    def backward(ctx, grad_query, grad_key, grad_value):
        if not ctx.needs_input_grad[0]:
            return None, None, None, None, None

        like = _first_not_none(grad_query, grad_key, grad_value)
        if like is None:
            raise RuntimeError(
                "gated_delta_post_conv_pack backward received no gradients"
            )

        batch_size, _, seq_length = ctx.input_shape
        query_shape = (
            batch_size,
            seq_length,
            ctx.num_v_heads,
            ctx.head_k_dim,
        )
        value_shape = (
            batch_size,
            seq_length,
            ctx.num_v_heads,
            ctx.head_v_dim,
        )
        grad_query = _zero_or_contiguous(grad_query, query_shape, like=like)
        grad_key = _zero_or_contiguous(grad_key, query_shape, like=like)
        grad_value = _zero_or_contiguous(grad_value, value_shape, like=like)

        grad_mixed_qkv = torch.empty_strided(
            ctx.input_shape,
            ctx.input_stride,
            dtype=like.dtype,
            device=like.device,
        )
        _m().gated_delta_post_conv_pack_backward(
            grad_mixed_qkv,
            grad_query,
            grad_key,
            grad_value,
            ctx.num_k_heads,
            ctx.num_v_heads,
            ctx.head_k_dim,
            ctx.head_v_dim,
        )
        return grad_mixed_qkv, None, None, None, None


class _GatedDeltaPostConvPackPreprocess(torch.autograd.Function):
    @staticmethod
    def forward(
        ctx,
        mixed_qkv: torch.Tensor,
        b: torch.Tensor,
        a: torch.Tensor,
        A_log: torch.Tensor,
        dt_bias: torch.Tensor,
        num_k_heads: int,
        num_v_heads: int,
        head_k_dim: int,
        head_v_dim: int,
    ):
        num_k_heads, num_v_heads, head_k_dim, head_v_dim = _check_args(
            mixed_qkv,
            num_k_heads,
            num_v_heads,
            head_k_dim,
            head_v_dim,
        )
        _check_gate_args(mixed_qkv, b, a, A_log, dt_bias, num_v_heads)

        batch_size, _, seq_length = mixed_qkv.shape
        query, key, value = _alloc_packed_qkv(
            batch_size,
            seq_length,
            num_v_heads,
            head_k_dim,
            head_v_dim,
            like=mixed_qkv,
        )
        beta = torch.empty(
            (batch_size, seq_length, num_v_heads),
            dtype=b.dtype,
            device=b.device,
        )
        g = torch.empty(
            (batch_size, seq_length, num_v_heads),
            dtype=torch.float32,
            device=mixed_qkv.device,
        )
        q_rstd = torch.empty(
            (batch_size, seq_length, num_k_heads),
            dtype=torch.float32,
            device=mixed_qkv.device,
        )
        k_rstd = torch.empty_like(q_rstd)

        _m().gated_delta_post_conv_pack_preprocess(
            query,
            key,
            value,
            beta,
            g,
            q_rstd,
            k_rstd,
            mixed_qkv,
            b,
            a,
            A_log,
            dt_bias,
            num_k_heads,
            num_v_heads,
            head_k_dim,
            head_v_dim,
        )

        ctx.input_shape = tuple(mixed_qkv.shape)
        ctx.input_stride = tuple(mixed_qkv.stride())
        ctx.num_k_heads = num_k_heads
        ctx.num_v_heads = num_v_heads
        ctx.head_k_dim = head_k_dim
        ctx.head_v_dim = head_v_dim
        ctx.save_for_backward(query, key, q_rstd, k_rstd, b, a, A_log, dt_bias)
        return query, key, value, beta, g

    @staticmethod
    def backward(ctx, grad_query, grad_key, grad_value, grad_beta, grad_g):
        if not any(ctx.needs_input_grad[:5]):
            return None, None, None, None, None, None, None, None, None

        query, key, q_rstd, k_rstd, b, a, A_log, dt_bias = ctx.saved_tensors
        batch_size, _, seq_length = ctx.input_shape
        query_shape = (
            batch_size,
            seq_length,
            ctx.num_v_heads,
            ctx.head_k_dim,
        )
        value_shape = (
            batch_size,
            seq_length,
            ctx.num_v_heads,
            ctx.head_v_dim,
        )
        gate_shape = (batch_size, seq_length, ctx.num_v_heads)

        grad_query = _zero_or_contiguous(grad_query, query_shape, like=query)
        grad_key = _zero_or_contiguous(grad_key, query_shape, like=key)
        grad_value = _zero_or_contiguous(grad_value, value_shape, like=query)
        grad_beta = _zero_or_contiguous(grad_beta, gate_shape, like=b)
        # q_rstd is saved fp32 on the right device, matching grad_g's expectations.
        grad_g = _zero_or_contiguous(grad_g, gate_shape, like=q_rstd)

        grad_mixed_qkv = torch.empty_strided(
            ctx.input_shape,
            ctx.input_stride,
            dtype=query.dtype,
            device=query.device,
        )
        grad_b = torch.empty_strided(
            tuple(b.shape),
            tuple(b.stride()),
            dtype=b.dtype,
            device=b.device,
        )
        grad_a = torch.empty_strided(
            tuple(a.shape),
            tuple(a.stride()),
            dtype=a.dtype,
            device=a.device,
        )
        grad_A_log = torch.zeros_like(A_log)
        grad_dt_bias = torch.zeros_like(dt_bias)

        _m().gated_delta_post_conv_pack_preprocess_backward(
            grad_mixed_qkv,
            grad_b,
            grad_a,
            grad_A_log,
            grad_dt_bias,
            grad_query,
            grad_key,
            grad_value,
            grad_beta,
            grad_g,
            query,
            key,
            q_rstd,
            k_rstd,
            b,
            a,
            A_log,
            dt_bias,
            ctx.num_k_heads,
            ctx.num_v_heads,
            ctx.head_k_dim,
            ctx.head_v_dim,
        )
        return (
            grad_mixed_qkv if ctx.needs_input_grad[0] else None,
            grad_b if ctx.needs_input_grad[1] else None,
            grad_a if ctx.needs_input_grad[2] else None,
            grad_A_log if ctx.needs_input_grad[3] else None,
            grad_dt_bias if ctx.needs_input_grad[4] else None,
            None,
            None,
            None,
            None,
        )


def gated_delta_post_conv_pack_kernel(
    mixed_qkv: torch.Tensor,
    num_k_heads: int,
    num_v_heads: int,
    head_k_dim: int,
    head_v_dim: int,
) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor]:
    return _GatedDeltaPostConvPack.apply(
        mixed_qkv,
        num_k_heads,
        num_v_heads,
        head_k_dim,
        head_v_dim,
    )


def gated_delta_post_conv_pack_preprocess_kernel(
    mixed_qkv: torch.Tensor,
    b: torch.Tensor,
    a: torch.Tensor,
    A_log: torch.Tensor,
    dt_bias: torch.Tensor,
    num_k_heads: int,
    num_v_heads: int,
    head_k_dim: int,
    head_v_dim: int,
) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor]:
    num_k_heads, num_v_heads, head_k_dim, head_v_dim = _check_args(
        mixed_qkv,
        num_k_heads,
        num_v_heads,
        head_k_dim,
        head_v_dim,
    )
    _check_gate_args(mixed_qkv, b, a, A_log, dt_bias, num_v_heads)

    if _can_use_preprocess_fast_path(
        mixed_qkv,
        b,
        a,
        A_log,
        dt_bias,
        num_k_heads,
        num_v_heads,
        head_k_dim,
        head_v_dim,
    ):
        return _GatedDeltaPostConvPackPreprocess.apply(
            mixed_qkv,
            b,
            a,
            A_log,
            dt_bias,
            num_k_heads,
            num_v_heads,
            head_k_dim,
            head_v_dim,
        )

    query, key, value = _GatedDeltaPostConvPack.apply(
        mixed_qkv,
        num_k_heads,
        num_v_heads,
        head_k_dim,
        head_v_dim,
    )
    query = _l2norm(query)
    key = _l2norm(key)
    beta = b.sigmoid()
    g = -A_log.float().exp() * F.softplus(a.float() + dt_bias.float())
    return query, key, value, beta, g





def _check_layout_tensor(
    tensor: torch.Tensor,
    name: str,
    *,
    expected_size: int,
    device: torch.device,
):
    if not isinstance(tensor, torch.Tensor):
        raise RuntimeError(f"{name} must be a tensor")
    if tensor.dim() != 1 or tensor.numel() != expected_size:
        raise RuntimeError(f"{name} must have shape [{expected_size}]")
    if tensor.dtype != torch.int64:
        raise RuntimeError(f"{name} must be int64")
    if tensor.device != device:
        raise RuntimeError(f"{name} must be on the same device as input")
    if not tensor.is_contiguous():
        raise RuntimeError(f"{name} must be contiguous")


def _check_inputs(
    text_qkv: torch.Tensor,
    action_qkv: torch.Tensor,
    action_starts: torch.Tensor,
    action_ends: torch.Tensor,
    action_offsets: torch.Tensor,
    q_weight: torch.Tensor,
    k_weight: torch.Tensor,
    q_action_weight: torch.Tensor,
    k_action_weight: torch.Tensor,
    num_heads: int,
    num_key_value_heads: int,
    head_dim: int,
):
    if text_qkv.is_cpu:
        raise RuntimeError("qwen35_vla_qkv_norm_replace expects CUDA tensors")
    if text_qkv.dim() != 3 or action_qkv.dim() != 3:
        raise RuntimeError("text_qkv and action_qkv must have shape [B, S, C]")
    if not text_qkv.is_contiguous():
        text_qkv = text_qkv.contiguous()
    if not action_qkv.is_contiguous():
        action_qkv = action_qkv.contiguous()
    if text_qkv.dtype not in (torch.float32, torch.float16, torch.bfloat16):
        raise RuntimeError(f"unsupported dtype: {text_qkv.dtype}")
    if action_qkv.dtype != text_qkv.dtype:
        raise RuntimeError("text_qkv and action_qkv must have the same dtype")
    # action_qkv is a packed action buffer indexed via action_offsets, not by
    # its batch dim, so B_a may be < B for mixed action+multimodal batches
    # (packed to only the action-bearing samples). Only guard against overflow.
    if action_qkv.shape[0] > text_qkv.shape[0]:
        raise RuntimeError("action_qkv batch rows must not exceed text_qkv batch")

    num_heads = int(num_heads)
    num_key_value_heads = int(num_key_value_heads)
    head_dim = int(head_dim)
    expected_qkv = (num_heads * 2 + num_key_value_heads * 2) * head_dim
    if text_qkv.shape[-1] != expected_qkv or action_qkv.shape[-1] != expected_qkv:
        raise RuntimeError(
            f"qkv hidden mismatch: expected {expected_qkv}, "
            f"got text={text_qkv.shape[-1]}, action={action_qkv.shape[-1]}"
        )

    batch_size = text_qkv.shape[0]
    _check_layout_tensor(
        action_starts,
        "action_starts",
        expected_size=batch_size,
        device=text_qkv.device,
    )
    _check_layout_tensor(
        action_ends,
        "action_ends",
        expected_size=batch_size,
        device=text_qkv.device,
    )
    _check_layout_tensor(
        action_offsets,
        "action_offsets",
        expected_size=batch_size + 1,
        device=text_qkv.device,
    )

    allowed_weight_dtypes = (torch.float32, torch.float16, torch.bfloat16)
    weights = []
    for weight, name in (
        (q_weight, "q_weight"),
        (k_weight, "k_weight"),
        (q_action_weight, "q_action_weight"),
        (k_action_weight, "k_action_weight"),
    ):
        if weight.dim() != 1 or weight.numel() != head_dim:
            raise RuntimeError(f"{name} must have shape [{head_dim}]")
        if weight.device != text_qkv.device:
            raise RuntimeError(f"{name} must be on the same device as input")
        if weight.dtype not in allowed_weight_dtypes:
            raise RuntimeError(f"{name} has unsupported dtype: {weight.dtype}")
        if not weight.is_contiguous():
            weight = weight.contiguous()
        weights.append(weight)

    return text_qkv, action_qkv, *weights


class _Qwen35VlaQkvNormReplace(torch.autograd.Function):
    @staticmethod
    def forward(
        ctx,
        text_qkv: torch.Tensor,
        action_qkv: torch.Tensor,
        action_starts: torch.Tensor,
        action_ends: torch.Tensor,
        action_offsets: torch.Tensor,
        q_weight: torch.Tensor,
        k_weight: torch.Tensor,
        q_action_weight: torch.Tensor,
        k_action_weight: torch.Tensor,
        num_heads: int,
        num_key_value_heads: int,
        head_dim: int,
        epsilon: float,
    ):
        (
            text_qkv,
            action_qkv,
            q_weight,
            k_weight,
            q_action_weight,
            k_action_weight,
        ) = _check_inputs(
            text_qkv,
            action_qkv,
            action_starts,
            action_ends,
            action_offsets,
            q_weight,
            k_weight,
            q_action_weight,
            k_action_weight,
            num_heads,
            num_key_value_heads,
            head_dim,
        )

        batch_size, seq_length, _ = text_qkv.shape
        action_length = action_qkv.shape[1]
        num_heads = int(num_heads)
        num_key_value_heads = int(num_key_value_heads)
        head_dim = int(head_dim)

        query = torch.empty(
            (batch_size, seq_length, num_heads, head_dim),
            dtype=text_qkv.dtype,
            device=text_qkv.device,
        )
        key = torch.empty(
            (batch_size, seq_length, num_key_value_heads, head_dim),
            dtype=text_qkv.dtype,
            device=text_qkv.device,
        )
        value = torch.empty_like(key)
        gate = torch.empty(
            (batch_size, seq_length, num_heads * head_dim),
            dtype=text_qkv.dtype,
            device=text_qkv.device,
        )

        _m().qwen35_vla_qkv_norm_replace_forward(
            query,
            key,
            value,
            gate,
            text_qkv,
            action_qkv,
            action_starts,
            action_ends,
            action_offsets,
            q_weight,
            k_weight,
            q_action_weight,
            k_action_weight,
            num_heads,
            num_key_value_heads,
            head_dim,
            float(epsilon),
        )

        ctx.save_for_backward(
            text_qkv,
            action_qkv,
            action_starts,
            action_ends,
            action_offsets,
            q_weight,
            k_weight,
            q_action_weight,
            k_action_weight,
        )
        ctx.num_heads = num_heads
        ctx.num_key_value_heads = num_key_value_heads
        ctx.head_dim = head_dim
        ctx.epsilon = float(epsilon)
        ctx.action_length = action_length
        return query, key, value, gate

    @staticmethod
    def backward(ctx, grad_query, grad_key, grad_value, grad_gate):
        (
            text_qkv,
            action_qkv,
            action_starts,
            action_ends,
            action_offsets,
            q_weight,
            k_weight,
            q_action_weight,
            k_action_weight,
        ) = ctx.saved_tensors

        if grad_query is None:
            grad_query = torch.zeros(
                (
                    text_qkv.shape[0],
                    text_qkv.shape[1],
                    ctx.num_heads,
                    ctx.head_dim,
                ),
                dtype=text_qkv.dtype,
                device=text_qkv.device,
            )
        elif not grad_query.is_contiguous():
            grad_query = grad_query.contiguous()

        if grad_key is None:
            grad_key = torch.zeros(
                (
                    text_qkv.shape[0],
                    text_qkv.shape[1],
                    ctx.num_key_value_heads,
                    ctx.head_dim,
                ),
                dtype=text_qkv.dtype,
                device=text_qkv.device,
            )
        elif not grad_key.is_contiguous():
            grad_key = grad_key.contiguous()

        if grad_value is None:
            grad_value = torch.zeros_like(grad_key)
        elif not grad_value.is_contiguous():
            grad_value = grad_value.contiguous()

        if grad_gate is None:
            grad_gate = torch.zeros(
                (
                    text_qkv.shape[0],
                    text_qkv.shape[1],
                    ctx.num_heads * ctx.head_dim,
                ),
                dtype=text_qkv.dtype,
                device=text_qkv.device,
            )
        elif not grad_gate.is_contiguous():
            grad_gate = grad_gate.contiguous()

        grad_text_qkv = torch.zeros_like(text_qkv)
        grad_action_qkv = torch.zeros_like(action_qkv)
        grad_q_weight = torch.zeros_like(q_weight, dtype=torch.float32)
        grad_k_weight = torch.zeros_like(k_weight, dtype=torch.float32)
        grad_q_action_weight = torch.zeros_like(q_action_weight, dtype=torch.float32)
        grad_k_action_weight = torch.zeros_like(k_action_weight, dtype=torch.float32)
        num_blocks = min(
            _get_sm_count() * 8,
            int(text_qkv.shape[0] * text_qkv.shape[1] * ctx.num_heads),
        )
        partial_dw = torch.empty(
            (4, num_blocks, ctx.head_dim),
            dtype=torch.float32,
            device=text_qkv.device,
        )

        _m().qwen35_vla_qkv_norm_replace_backward(
            grad_text_qkv,
            grad_action_qkv,
            grad_q_weight,
            grad_k_weight,
            grad_q_action_weight,
            grad_k_action_weight,
            partial_dw,
            grad_query,
            grad_key,
            grad_value,
            grad_gate,
            text_qkv,
            action_qkv,
            action_starts,
            action_ends,
            action_offsets,
            q_weight,
            k_weight,
            q_action_weight,
            k_action_weight,
            ctx.num_heads,
            ctx.num_key_value_heads,
            ctx.head_dim,
            ctx.epsilon,
        )

        return (
            grad_text_qkv,
            grad_action_qkv,
            None,
            None,
            None,
            grad_q_weight,
            grad_k_weight,
            grad_q_action_weight,
            grad_k_action_weight,
            None,
            None,
            None,
            None,
        )


def qwen35_vla_qkv_norm_replace_kernel(
    text_qkv: torch.Tensor,
    action_qkv: torch.Tensor,
    action_starts: torch.Tensor,
    action_ends: torch.Tensor,
    action_offsets: torch.Tensor,
    q_weight: torch.Tensor,
    k_weight: torch.Tensor,
    q_action_weight: torch.Tensor,
    k_action_weight: torch.Tensor,
    num_heads: int,
    num_key_value_heads: int,
    head_dim: int,
    epsilon: float,
) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor]:
    return _Qwen35VlaQkvNormReplace.apply(
        text_qkv,
        action_qkv,
        action_starts,
        action_ends,
        action_offsets,
        q_weight,
        k_weight,
        q_action_weight,
        k_action_weight,
        num_heads,
        num_key_value_heads,
        head_dim,
        epsilon,
    )


"""Python binding for the ``qwen35_rvq_position_ids`` CUDA kernel.

Rewrites mrope position ids for serialized RVQ action spans. The entry point
mirrors the wall-x PyTorch fallback contract
(``wall_x/model/core/ops/seq_rvq.py::qwen35_rvq_position_ids_pytorch``):

- same signature (``input_ids, position_ids, *, start_token_id, level_lut,
  num_latents, num_quantizers, time_major, reference=None``),
- same return: ``[4, B, L]`` int64 (a 3-route input is expanded to 4 routes by
  duplicating route 0),
- same hot-path sync budget: exactly one device->host sync
  (``bool(err.any())``),
- same error behavior: on an invalid RVQ span, either call ``reference()``
  (expected to raise the detailed legacy message) or run the internal slow
  re-check that raises the identical ValueError messages.
"""




def _check_rvq_position_inputs(input_ids, position_ids):
    if not isinstance(input_ids, torch.Tensor) or not isinstance(
        position_ids, torch.Tensor
    ):
        raise RuntimeError("input_ids and position_ids must be tensors")
    if input_ids.ndim != 2:
        raise ValueError(f"input_ids must have shape [B,L], got {input_ids.shape}")
    if position_ids.ndim != 3 or position_ids.shape[0] not in (3, 4):
        raise ValueError(
            "position_ids must have shape [3|4,B,L], got " f"{position_ids.shape}"
        )
    if tuple(position_ids.shape[-2:]) != tuple(input_ids.shape):
        raise ValueError(
            f"input/position shapes differ: {input_ids.shape} vs "
            f"{position_ids.shape}"
        )
    if not input_ids.is_cuda or not position_ids.is_cuda:
        raise RuntimeError("qwen35_rvq_position_ids requires CUDA tensors")
    if input_ids.device != position_ids.device:
        raise RuntimeError("input_ids and position_ids must be on the same device")
    if position_ids.dtype != torch.int64:
        raise RuntimeError(f"position_ids must be int64, got {position_ids.dtype}")


def _raise_rvq_span_error(
    input_ids,
    *,
    start_token_id,
    level_lut,
    num_latents,
    num_quantizers,
    time_major,
):
    """Slow re-check reproducing the wall-x reference error messages (and its
    batch -> span -> slot iteration order). Only reached after the kernel
    flagged an error, so syncs are fine here."""
    num_code_tokens = num_latents * num_quantizers
    ids_cpu = input_ids.detach().cpu()
    lut_cpu = level_lut.detach().cpu()
    lut_len = lut_cpu.numel()
    seq_len = ids_cpu.shape[1]
    for batch_idx in range(ids_cpu.shape[0]):
        starts = (ids_cpu[batch_idx] == start_token_id).nonzero().flatten().tolist()
        for start in starts:
            end = start + 1 + num_code_tokens
            if end > seq_len:
                raise ValueError(
                    f"RVQ span at token {start} needs {num_code_tokens} "
                    "code tokens but reaches the sequence end"
                )
            for slot in range(num_code_tokens):
                if time_major:
                    level = slot % num_quantizers
                else:
                    level = slot // num_latents
                token = int(ids_cpu[batch_idx, start + 1 + slot])
                token_level = int(lut_cpu[token]) if 0 <= token < lut_len else -1
                if token_level != level:
                    raise ValueError(
                        f"RVQ level {level} slot contains token id {token}, "
                        "which belongs to a different level"
                    )
    raise RuntimeError(
        "qwen35_rvq_position_ids flagged an invalid RVQ span, but the detailed "
        "re-check found none; level_lut and span geometry disagree"
    )


def qwen35_rvq_position_ids_kernel(
    input_ids,
    position_ids,
    *,
    start_token_id,
    level_lut,
    num_latents,
    num_quantizers,
    time_major,
    reference=None,
):
    _check_rvq_position_inputs(input_ids, position_ids)
    if not isinstance(level_lut, torch.Tensor) or level_lut.ndim != 1:
        raise RuntimeError("level_lut must be a 1-D tensor")
    if level_lut.device != input_ids.device:
        raise RuntimeError("level_lut must be on the same device as input_ids")

    input_ids = input_ids.long().contiguous()
    lut = level_lut.contiguous()
    if lut.dtype != torch.int8:
        lut = lut.to(torch.int8)

    # 3-route input: expand to 4 routes by duplicating route 0 (same as the
    # fallback's torch.cat((position_ids[:1], position_ids))).
    output = (
        torch.cat((position_ids[:1], position_ids), dim=0)
        if position_ids.shape[0] == 3
        else position_ids.clone()
    ).contiguous()

    err = torch.zeros(input_ids.shape[0], dtype=torch.int32, device=input_ids.device)
    _m().qwen35_rvq_position_ids(
        output,
        input_ids,
        lut,
        err,
        int(start_token_id),
        int(num_latents),
        int(num_quantizers),
        bool(time_major),
    )
    if bool(err.any()):  # the one allowed sync; True only on the error path
        if reference is not None:
            reference()
            raise RuntimeError(
                "qwen35_rvq_position_ids flagged an invalid RVQ span, but the "
                "reference implementation did not raise"
            )
        _raise_rvq_span_error(
            input_ids,
            start_token_id=start_token_id,
            level_lut=lut,
            num_latents=num_latents,
            num_quantizers=num_quantizers,
            time_major=time_major,
        )
    return output


